// ---- helpers ----

func onIf(b bool) string {
	if b {
		return " is-on"
	}
	return ""
}

func splitPath(p string) []string { return strings.Split(p, "/") }

func nextURL(id string) string {
	if id == "" {
		return "/"
	}
	return "/diff/" + id
}

func sbRowClass(item *review.Item, activeID string) string {
	cls := "sb-row"
	switch item.Diff.Status.String() {
	case "added":
		cls += " is-added"
	case "modified":
		cls += " is-modified"
	case "deleted":
		cls += " is-deleted"
	}
	switch item.Verdict.Status {
	case review.StatusApproved:
		cls += " is-approved"
	case review.StatusRejected:
		cls += " is-rejected"
	}
	if item.ID == activeID {
		cls += " is-current"
	}
	return cls
}

func fileTag(item *review.Item) string {
	switch item.Diff.Status.String() {
	case "added":
		return "A"
	case "modified":
		return "M"
	case "deleted":
		return "D"
	}
	return "?"
}

func verdictMini(s review.VerdictStatus) string {
	switch s {
	case review.StatusApproved:
		return "ok"
	case review.StatusRejected:
		return "no"
	}
	return "…"
}

